def harmonize_value(value, ref_info):
    if pd.isna(value):
        return np.nan

    min_range, max_range = ref_info['normal_range']
    conversion = ref_info.get('conversion')

    if min_range <= value <= max_range:
        return value

    if conversion is None:
        return value

    margin = 0.15
    min_accept = min_range * (1 - margin)
    max_accept = max_range * (1 + margin)

    if value > max_range:
        converted = value * conversion
        if min_accept <= converted <= max_accept:
            return converted
        converted = value / conversion
        if min_accept <= converted <= max_accept:
            return converted

    if value < min_range:
        converted = value / conversion
        if min_accept <= converted <= max_accept:
            return converted
        converted = value * conversion
        if min_accept <= converted <= max_accept:
            return converted

    return value

ref_info = {
    'normal_range': (25, 900),
    'conversion': 18.0,
}

# Test
test_vals = [2.921, 1.11, 1.443, 4.418]
for v in test_vals:
    result = harmonize_value(v, ref_info)
    print(f"Input: {v}, Output: {result:.2f}")
